import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { randomUUID } from 'node:crypto';
import { readFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { mkdir } from 'node:fs/promises';

const root = dirname(fileURLToPath(import.meta.url));
const dbPath = resolve(process.env.DB_PATH || resolve(root, 'data/workboard.sqlite'));
await mkdir(dirname(dbPath), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  archived INTEGER NOT NULL DEFAULT 0
)`);
try { db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0'); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}
try { db.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal' CHECK(default_priority IN ('Low', 'Normal', 'High'))"); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL,
  priority TEXT NOT NULL DEFAULT 'Normal' CHECK(priority IN ('Low', 'Normal', 'High'))
)`);
try { db.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK(priority IN ('Low', 'Normal', 'High'))"); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}
try { db.exec('ALTER TABLE tasks ADD COLUMN due_date TEXT'); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}
try { db.exec("ALTER TABLE tasks ADD COLUMN notes TEXT NOT NULL DEFAULT ''"); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}
db.exec(`CREATE TABLE IF NOT EXISTS task_project_positions (
  task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  PRIMARY KEY (task_id, project_id),
  UNIQUE (project_id, position)
)`);
db.exec(`INSERT OR IGNORE INTO task_project_positions (task_id, project_id, position)
  SELECT id, project_id, ROW_NUMBER() OVER (PARTITION BY project_id ORDER BY created_at, rowid)
  FROM tasks`);
function transaction(callback) {
  db.exec('BEGIN');
  try {
    const result = callback();
    db.exec('COMMIT');
    return result;
  } catch (error) {
    db.exec('ROLLBACK');
    throw error;
  }
}

const insertProject = db.prepare('INSERT INTO projects (id, name, created_at) VALUES (?, ?, ?)');
const insertTask = db.prepare('INSERT INTO tasks (id, project_id, title, completed, created_at, priority) VALUES (?, ?, ?, 0, ?, ?)');
const listTasks = db.prepare(`SELECT t.id, t.project_id AS projectId, t.title, t.completed, t.priority, t.due_date AS dueDate, t.notes
  FROM tasks t JOIN task_project_positions p ON p.task_id = t.id AND p.project_id = t.project_id
  WHERE t.project_id = ? ORDER BY p.position`);
const getTask = db.prepare('SELECT id, project_id AS projectId, title, completed, priority, due_date AS dueDate, notes FROM tasks WHERE id = ?');
const setTaskPriority = db.prepare('UPDATE tasks SET priority = ? WHERE id = ?');
const setTaskCompletion = db.prepare('UPDATE tasks SET completed = ? WHERE id = ?');
const renameTask = db.prepare('UPDATE tasks SET title = ? WHERE id = ?');
const setTaskDueDate = db.prepare('UPDATE tasks SET due_date = ? WHERE id = ?');
const moveTask = db.prepare('UPDATE tasks SET project_id = ? WHERE id = ?');
const listProjects = db.prepare(`SELECT p.id, p.name, p.archived,
  COUNT(t.id) AS totalCount, COALESCE(SUM(t.completed), 0) AS completedCount
  FROM projects p LEFT JOIN tasks t ON t.project_id = p.id
  WHERE p.archived = ? GROUP BY p.id ORDER BY p.created_at, p.rowid`);
const getProject = db.prepare('SELECT id, name, archived, default_priority AS defaultPriority FROM projects WHERE id = ?');
const setArchived = db.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = db.prepare('UPDATE projects SET name = ? WHERE id = ?');
const indexHtml = await readFile(resolve(root, 'public/index.html'));
const appJs = await readFile(resolve(root, 'public/app.js'));
const appCss = await readFile(resolve(root, 'public/style.css'));

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  const send = (status, body, type = 'application/json; charset=utf-8') => {
    res.writeHead(status, { 'Content-Type': type, 'X-Content-Type-Options': 'nosniff' });
    res.end(body);
  };
  try {
    if (req.method === 'GET' && url.pathname === '/health') return send(200, JSON.stringify({ status: 'ok' }));
    if (req.method === 'GET' && url.pathname === '/api/projects') {
      const archived = url.searchParams.get('archived') === 'true' ? 1 : 0;
      return send(200, JSON.stringify(listProjects.all(archived)));
    }
    const archiveMatch = url.pathname.match(/^\/api\/projects\/([^/]+)\/archive$/);
    if (req.method === 'PATCH' && archiveMatch) {
      const project = getProject.get(archiveMatch[1]);
      if (!project) return send(404, JSON.stringify({ error: 'Project not found' }));
      let raw = '';
      for await (const chunk of req) raw += chunk;
      let payload;
      try { payload = JSON.parse(raw); } catch { return send(400, JSON.stringify({ error: 'Invalid JSON' })); }
      if (typeof payload?.archived !== 'boolean') return send(400, JSON.stringify({ error: 'Invalid archive state' }));
      setArchived.run(payload.archived ? 1 : 0, project.id);
      return send(200, JSON.stringify({ ...project, archived: payload.archived ? 1 : 0 }));
    }
    if (req.method === 'POST' && url.pathname === '/api/projects') {
      let raw = '';
      for await (const chunk of req) raw += chunk;
      let payload;
      try { payload = JSON.parse(raw); } catch { return send(400, JSON.stringify({ error: 'Invalid JSON' })); }
      const name = typeof payload?.name === 'string' ? payload.name.trim() : '';
      if (!name) return send(400, JSON.stringify({ error: 'Project name is required' }));
      const id = randomUUID();
      insertProject.run(id, name, Date.now());
      return send(201, JSON.stringify({ id, name }));
    }
    const renameMatch = url.pathname.match(/^\/api\/projects\/([^/]+)$/);
    if (req.method === 'PATCH' && renameMatch) {
      const project = getProject.get(renameMatch[1]);
      if (!project) return send(404, JSON.stringify({ error: 'Project not found' }));
      if (project.archived) return send(409, JSON.stringify({ error: 'Archived project cannot be changed' }));
      let raw = '';
      for await (const chunk of req) raw += chunk;
      let payload;
      try { payload = JSON.parse(raw); } catch { return send(400, JSON.stringify({ error: 'Invalid JSON' })); }
      const name = typeof payload?.name === 'string' ? payload.name.trim() : '';
      if (['Low', 'Normal', 'High'].includes(payload?.defaultPriority)) {
        db.prepare('UPDATE projects SET default_priority = ? WHERE id = ?').run(payload.defaultPriority, project.id);
        return send(200, JSON.stringify({ ...project, defaultPriority: payload.defaultPriority }));
      }
      if (!name) return send(400, JSON.stringify({ error: 'Project name is required' }));
      renameProject.run(name, project.id);
      return send(200, JSON.stringify({ ...project, name }));
    }
    const tasksMatch = url.pathname.match(/^\/api\/projects\/([^/]+)\/tasks$/);
    if (tasksMatch && (req.method === 'GET' || req.method === 'POST')) {
      const project = getProject.get(tasksMatch[1]);
      if (!project) return send(404, JSON.stringify({ error: 'Project not found' }));
      if (req.method === 'GET') return send(200, JSON.stringify(listTasks.all(tasksMatch[1])));
      if (project.archived) return send(409, JSON.stringify({ error: 'Archived project cannot be changed' }));
      let raw = '';
      for await (const chunk of req) raw += chunk;
      let payload;
      try { payload = JSON.parse(raw); } catch { return send(400, JSON.stringify({ error: 'Invalid JSON' })); }
      const title = typeof payload?.title === 'string' ? payload.title.trim() : '';
      if (!title) return send(400, JSON.stringify({ error: 'Task title is required' }));
      const task = { id: randomUUID(), projectId: tasksMatch[1], title, completed: 0 };
      task.priority = project.defaultPriority;
      const create = () => transaction(() => {
        insertTask.run(task.id, task.projectId, task.title, Date.now(), task.priority);
        const position = db.prepare('SELECT COALESCE(MAX(position), 0) + 1 AS value FROM task_project_positions WHERE project_id = ?').get(task.projectId).value;
        db.prepare('INSERT INTO task_project_positions (task_id, project_id, position) VALUES (?, ?, ?)').run(task.id, task.projectId, position);
      });
      create();
      return send(201, JSON.stringify(task));
    }
    const moveMatch = url.pathname.match(/^\/api\/tasks\/([^/]+)\/move$/);
    if (req.method === 'POST' && moveMatch) {
      let raw = '';
      for await (const chunk of req) raw += chunk;
      let payload;
      try { payload = JSON.parse(raw); } catch { return send(400, JSON.stringify({ error: 'Invalid JSON' })); }
      const task = getTask.get(moveMatch[1]);
      if (!task) return send(404, JSON.stringify({ error: 'Task not found' }));
      const source = getProject.get(task.projectId);
      const destination = getProject.get(payload?.destinationProjectId);
      if (source.archived || !destination || destination.archived || destination.id === source.id) return send(400, JSON.stringify({ error: 'Invalid destination project' }));
      const move = () => transaction(() => {
        const knownPosition = db.prepare('SELECT position FROM task_project_positions WHERE task_id = ? AND project_id = ?').get(task.id, destination.id);
        let position = knownPosition?.position;
        if (position === undefined) {
          position = db.prepare('SELECT COALESCE(MAX(position), 0) + 1 AS value FROM task_project_positions WHERE project_id = ?').get(destination.id).value;
          db.prepare('INSERT INTO task_project_positions (task_id, project_id, position) VALUES (?, ?, ?)').run(task.id, destination.id, position);
        }
        moveTask.run(destination.id, task.id);
      });
      move();
      return send(200, JSON.stringify({ ...task, projectId: destination.id }));
    }
    const taskMatch = url.pathname.match(/^\/api\/tasks\/([^/]+)$/);
    if (req.method === 'PATCH' && taskMatch) {
      let raw = '';
      for await (const chunk of req) raw += chunk;
      let payload;
      try { payload = JSON.parse(raw); } catch { return send(400, JSON.stringify({ error: 'Invalid JSON' })); }
      const task = getTask.get(taskMatch[1]);
      if (!task) return send(404, JSON.stringify({ error: 'Task not found' }));
      if (getProject.get(task.projectId).archived) return send(409, JSON.stringify({ error: 'Archived project cannot be changed' }));
      if (typeof payload?.completed === 'boolean') {
        setTaskCompletion.run(payload.completed ? 1 : 0, task.id);
        return send(200, JSON.stringify({ ...task, completed: payload.completed ? 1 : 0 }));
      }
      if (Object.hasOwn(payload ?? {}, 'notes')) {
        if (typeof payload.notes !== 'string') return send(400, JSON.stringify({ error: 'Notes must be text' }));
        db.prepare('UPDATE tasks SET notes = ? WHERE id = ?').run(payload.notes, task.id);
        return send(200, JSON.stringify({ ...task, notes: payload.notes }));
      }
      if (Object.hasOwn(payload ?? {}, 'dueDate')) {
        if (typeof payload.dueDate !== 'string') return send(400, JSON.stringify({ error: 'Due date must be a valid YYYY-MM-DD date' }));
        const dueDate = payload.dueDate.trim();
        if (dueDate && !isValidDueDate(dueDate)) return send(400, JSON.stringify({ error: 'Due date must be a valid YYYY-MM-DD date' }));
        setTaskDueDate.run(dueDate || null, task.id);
        return send(200, JSON.stringify({ ...task, dueDate: dueDate || null }));
      }
      if (['Low', 'Normal', 'High'].includes(payload?.priority)) {
        setTaskPriority.run(payload.priority, task.id);
        return send(200, JSON.stringify({ ...task, priority: payload.priority }));
      }
      const title = typeof payload?.title === 'string' ? payload.title.trim() : '';
      if (!title) return send(400, JSON.stringify({ error: 'Task title is required' }));
      renameTask.run(title, task.id);
      return send(200, JSON.stringify({ ...task, title }));
    }
    const projectMatch = url.pathname.match(/^\/api\/projects\/([^/]+)$/);
    if (req.method === 'GET' && projectMatch) {
      const project = getProject.get(projectMatch[1]);
      return project ? send(200, JSON.stringify(project)) : send(404, JSON.stringify({ error: 'Project not found' }));
    }
    if (req.method === 'GET' && (url.pathname === '/' || /^\/projects\/[^/]+\/?$/.test(url.pathname))) return send(200, indexHtml, 'text/html; charset=utf-8');
    if (req.method === 'GET' && url.pathname === '/app.js') return send(200, appJs, 'text/javascript; charset=utf-8');
    if (req.method === 'GET' && url.pathname === '/style.css') return send(200, appCss, 'text/css; charset=utf-8');
    return send(404, JSON.stringify({ error: 'Not found' }));
  } catch (error) {
    console.error(error);
    return send(500, JSON.stringify({ error: 'Internal server error' }));
  }
});

function isValidDueDate(value) {
  const match = value.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return false;
  const [, yearText, monthText, dayText] = match;
  const year = Number(yearText), month = Number(monthText), day = Number(dayText);
  if (year < 1 || month < 1 || month > 12) return false;
  const days = [31, year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day >= 1 && day <= days[month - 1];
}

const port = Number.parseInt(process.env.PORT || '8080', 10);
server.listen(port, '0.0.0.0', () => console.log(`Workboard listening on ${port}`));

const app = document.querySelector('#app');
const projectViewState = new Map();
const normalizeSearch = value => value.replace(/[ \t]+/g, ' ').replace(/[A-Z]/g, character => character.toLowerCase());

async function request(path, options) {
  const response = await fetch(path, options);
  const body = await response.json();
  if (!response.ok) throw new Error(body.error || 'Request failed');
  return body;
}

function element(tag, attributes = {}, text = '') {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(attributes)) node.setAttribute(key, value);
  if (text) node.textContent = text;
  return node;
}

async function render() {
  app.replaceChildren();
  const match = window.location.pathname.match(/^\/projects\/([^/]+)\/?$/);
  if (match) {
    let project;
    try { project = await request(`/api/projects/${encodeURIComponent(match[1])}`); } catch { project = null; }
    const back = element('button', { type: 'button' }, 'Projects');
    back.addEventListener('click', () => { projectViewState.delete(match[1]); history.pushState({}, '', '/'); render(); });
    app.append(back);
    if (!project) { app.append(element('p', { role: 'alert' }, 'Project not found')); return; }
    app.append(element('h1', {}, project.name));
    if (project.archived) app.append(element('p', {}, 'Archived project'));
    const renameForm = element('form');
    const renameLabel = element('label', { for: 'new-project-name' }, 'New project name');
    const renameInput = element('input', { id: 'new-project-name', name: 'name', type: 'text' });
    const renameButton = element('button', { type: 'submit' }, 'Rename project');
    const renameAlert = element('p', { role: 'alert', hidden: '' });
    if (project.archived) { renameInput.disabled = true; renameButton.disabled = true; }
    renameForm.append(renameLabel, renameInput, renameButton, renameAlert);
    renameForm.addEventListener('submit', async event => {
      event.preventDefault();
      const name = renameInput.value.trim();
      if (!name) { renameAlert.textContent = 'Project name is required'; renameAlert.hidden = false; renameInput.focus(); return; }
      try {
        await request(`/api/projects/${encodeURIComponent(match[1])}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }) });
        render();
      } catch (error) { renameAlert.textContent = error.message; renameAlert.hidden = false; }
    });
    app.append(renameForm);
    const defaultPriorityLabel = element('label', { for: 'default-task-priority' }, 'Default task priority');
    const defaultPriority = element('select', { id: 'default-task-priority' });
    for (const value of ['Low', 'Normal', 'High']) defaultPriority.append(element('option', { value }, value));
    defaultPriority.value = project.defaultPriority || 'Normal';
    defaultPriority.disabled = Boolean(project.archived);
    defaultPriority.addEventListener('change', async () => {
      try {
        await request(`/api/projects/${encodeURIComponent(match[1])}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ defaultPriority: defaultPriority.value }) });
      } catch { defaultPriority.value = project.defaultPriority || 'Normal'; }
    });
    app.append(defaultPriorityLabel, defaultPriority);
    const form = element('form');
    const label = element('label', { for: 'task-title' }, 'Task title');
    const input = element('input', { id: 'task-title', name: 'title', type: 'text' });
    const submit = element('button', { type: 'submit' }, 'Create task');
    const alert = element('p', { role: 'alert', hidden: '' });
    if (project.archived) { input.disabled = true; submit.disabled = true; }
    form.append(label, input, submit, alert);
    const filterLabel = element('label', { for: 'task-filter' }, 'Task filter');
    const filter = element('select', { id: 'task-filter' });
    for (const value of ['All', 'Open', 'Completed']) filter.append(element('option', { value }, value));
    const priorityFilterLabel = element('label', { for: 'priority-filter' }, 'Priority filter');
    const priorityFilter = element('select', { id: 'priority-filter' });
    for (const value of ['All', 'Low', 'Normal', 'High']) priorityFilter.append(element('option', { value }, value));
    const dueFromLabel = element('label', { for: 'due-from' }, 'Due from');
    const dueFrom = element('input', { id: 'due-from', type: 'text', 'aria-label': 'Due from' });
    const dueThroughLabel = element('label', { for: 'due-through' }, 'Due through');
    const dueThrough = element('input', { id: 'due-through', type: 'text', 'aria-label': 'Due through' });
    const applyDueRange = element('button', { type: 'button' }, 'Apply due range');
    const rangeAlert = element('p', { role: 'alert', hidden: '' });
    const viewState = projectViewState.get(match[1]) || { appliedFrom: '', appliedThrough: '', dueFrom: '', dueThrough: '', taskFilter: 'All', priorityFilter: 'All', taskQuery: '', taskInput: '' };
    let appliedFrom = viewState.appliedFrom, appliedThrough = viewState.appliedThrough;
    dueFrom.value = viewState.dueFrom;
    dueThrough.value = viewState.dueThrough;
    let taskQuery = viewState.taskQuery;
    const taskSearchInput = element('input', { type: 'text', 'aria-label': 'Task search', value: viewState.taskInput });
    const taskSearchButton = element('button', { type: 'button' }, 'Search tasks');
    filter.value = viewState.taskFilter;
    priorityFilter.value = viewState.priorityFilter;
    const saveViewState = () => {
      projectViewState.set(match[1], { appliedFrom, appliedThrough, dueFrom: dueFrom.value, dueThrough: dueThrough.value, taskFilter: filter.value, priorityFilter: priorityFilter.value, taskQuery, taskInput: taskSearchInput.value });
    };
    dueFrom.addEventListener('input', saveViewState);
    dueThrough.addEventListener('input', saveViewState);
    taskSearchInput.addEventListener('input', saveViewState);
    taskSearchButton.addEventListener('click', () => { taskQuery = taskSearchInput.value.trim(); saveViewState(); refresh(); });
    const destinations = await request('/api/projects?archived=false');
    const eligibleDestinations = destinations.filter(item => item.id !== project.id);
    const tasks = element('section', { 'aria-label': 'Tasks' });
    app.append(form, filterLabel, filter, priorityFilterLabel, priorityFilter,
      dueFromLabel, dueFrom, dueThroughLabel, dueThrough, applyDueRange, rangeAlert,
      taskSearchInput, taskSearchButton, tasks);
    const refresh = async () => {
      const items = await request(`/api/projects/${encodeURIComponent(match[1])}/tasks`);
      tasks.replaceChildren();
      for (const task of items) {
        if (!normalizeSearch(task.title).includes(normalizeSearch(taskQuery))) continue;
        if ((filter.value === 'Open' && task.completed) || (filter.value === 'Completed' && !task.completed)) continue;
        if (priorityFilter.value !== 'All' && task.priority !== priorityFilter.value) continue;
        if ((appliedFrom || appliedThrough) && (!task.dueDate ||
          (appliedFrom && task.dueDate < appliedFrom) ||
          (appliedThrough && task.dueDate > appliedThrough))) continue;
        const row = element('div', { 'data-testid': 'task-row', class: 'project-row' });
        row.append(element('span', {}, task.title));
        const renameInput = element('input', { type: 'text', 'aria-label': 'New task title', value: task.title });
        const renameButton = element('button', { type: 'button' }, 'Rename task');
        const renameAlert = element('span', { role: 'alert', hidden: '' });
        renameInput.disabled = Boolean(project.archived);
        renameButton.disabled = Boolean(project.archived);
        renameButton.addEventListener('click', async () => {
          const title = renameInput.value.trim();
          if (!title) { renameAlert.textContent = 'Task title is required'; renameAlert.hidden = false; renameInput.focus(); return; }
          try {
            await request(`/api/tasks/${encodeURIComponent(task.id)}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }) });
            await refresh();
          } catch (error) { renameAlert.textContent = error.message; renameAlert.hidden = false; }
        });
        row.append(renameInput, renameButton, renameAlert);
        const priority = element('select', { 'aria-label': 'Task priority' });
        for (const value of ['Low', 'Normal', 'High']) priority.append(element('option', { value }, value));
        priority.value = task.priority || 'Normal';
        priority.disabled = Boolean(project.archived);
        priority.addEventListener('change', async () => {
          try {
            await request(`/api/tasks/${encodeURIComponent(task.id)}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ priority: priority.value }) });
            await refresh();
          } catch (error) { priority.value = task.priority || 'Normal'; }
        });
        row.append(priority);
        const dueDate = element('input', { type: 'text', 'aria-label': 'Task due date', value: task.dueDate || '' });
        const saveDueDate = element('button', { type: 'button', 'aria-label': 'Save due date' }, 'Save due date');
        const dueDateAlert = element('span', { role: 'alert', hidden: '' });
        dueDate.disabled = Boolean(project.archived);
        saveDueDate.disabled = Boolean(project.archived);
        saveDueDate.addEventListener('click', async () => {
          try {
            await request(`/api/tasks/${encodeURIComponent(task.id)}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ dueDate: dueDate.value }) });
            dueDateAlert.hidden = true;
            await refresh();
          } catch (error) { dueDateAlert.textContent = error.message; dueDateAlert.hidden = false; }
        });
        row.append(dueDate, saveDueDate, dueDateAlert);
        const notes = element('textarea', { 'aria-label': 'Task notes', rows: '3' });
        notes.value = task.notes || '';
        const saveNotes = element('button', { type: 'button', 'aria-label': 'Save notes' }, 'Save notes');
        const notesAlert = element('span', { role: 'alert', hidden: '' });
        notes.disabled = Boolean(project.archived);
        saveNotes.disabled = Boolean(project.archived);
        saveNotes.addEventListener('click', async () => {
          try {
            await request(`/api/tasks/${encodeURIComponent(task.id)}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ notes: notes.value }) });
            notesAlert.hidden = true;
            await refresh();
          } catch (error) { notesAlert.textContent = error.message; notesAlert.hidden = false; }
        });
        row.append(notes, saveNotes, notesAlert);
        const checkbox = element('input', { type: 'checkbox', 'aria-label': `Complete ${task.title}` });
        checkbox.checked = Boolean(task.completed);
        checkbox.disabled = Boolean(project.archived);
        checkbox.addEventListener('change', async () => {
          await request(`/api/tasks/${encodeURIComponent(task.id)}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
          await refresh();
        });
        row.append(checkbox);
        const destination = element('select', { 'aria-label': 'Destination project' });
        for (const item of eligibleDestinations) destination.append(element('option', { value: item.id }, item.name));
        const moveButton = element('button', { type: 'button' }, 'Move task');
        destination.disabled = Boolean(project.archived) || eligibleDestinations.length === 0;
        moveButton.disabled = Boolean(project.archived) || eligibleDestinations.length === 0;
        moveButton.addEventListener('click', async () => {
          try {
            await request(`/api/tasks/${encodeURIComponent(task.id)}/move`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ destinationProjectId: destination.value }) });
            await refresh();
          } catch (error) { moveAlert.textContent = error.message; moveAlert.hidden = false; }
